import { resolve, join } from 'node:path';
import { readdirSync } from 'node:fs';
import { readEval, buildEvalBundle, manifestIssues } from '../runs/optimization-7de9cda/atira.mjs';

const bundlesDir = resolve('../evals/bundles');
const bundles = readdirSync(bundlesDir).filter(f => !f.startsWith('.'));

console.log(`Auditing ${bundles.length} bundles under ${bundlesDir}...\n`);

for (const slug of bundles) {
  const dir = join(bundlesDir, slug);
  try {
    const checked = readEval(dir);
    const bundle = buildEvalBundle(dir);
    const manifestProblems = manifestIssues(checked.manifest);

    console.log(`[PASS] ${slug}:`);
    console.log(`  - Manifest sites: ${checked.manifest.sites.map(s => `${s.name}:${s.port}`).join(', ')}`);
    console.log(`  - Start command: "${checked.manifest.start}"`);
    console.log(`  - World mode: "${checked.manifest.world}"`);
    console.log(`  - Brief bytes: ${checked.brief.length} (max 65536)`);
    console.log(`  - Expected bid schema valid: true`);
    console.log(`  - Bundle file count: ${bundle.files.length}, gzip size: ${bundle.gzip.length} bytes`);
    console.log(`  - Skipped files count: ${bundle.skipped.length}`);
    if (manifestProblems.length > 0) {
      console.log(`  - Manifest warnings/issues:`, manifestProblems);
    }
  } catch (err) {
    console.log(`[FAIL] ${slug}:`);
    console.log(`  Error: ${err.message}`);
    if (err.issues) {
      console.log(`  Issues:`, err.issues);
    }
  }
}

